-- Atomic, owner-scoped library replication. Cursor values are allocated while
-- holding the owner row lock, so they are committed in order and never depend on device clocks.
create table if not exists public.library_nodes (id uuid primary key, owner_id uuid not null references auth.users(id) on delete cascade, parent_id uuid, kind text not null check(kind in ('folder','song')), name text not null, sort_order bigint not null, song jsonb, rev bigint not null, deleted_at timestamptz, created_at timestamptz not null, updated_at timestamptz not null);
create table if not exists public.document_versions (id uuid primary key, owner_id uuid not null references auth.users(id) on delete cascade, document_id uuid not null, reason text not null, title text not null, payload jsonb not null, created_at timestamptz not null);
create table if not exists public.sync_cursors (owner_id uuid primary key references auth.users(id) on delete cascade, value bigint not null default 0);
create table if not exists public.sync_changes (owner_id uuid not null references auth.users(id) on delete cascade, cursor bigint not null, kind text not null check(kind in ('node','document','version')), record jsonb not null, primary key(owner_id,cursor));
alter table public.library_nodes enable row level security; alter table public.document_versions enable row level security; alter table public.sync_cursors enable row level security; alter table public.sync_changes enable row level security;
create policy "own nodes" on public.library_nodes for all using(owner_id=auth.uid()) with check(owner_id=auth.uid()); create policy "own versions" on public.document_versions for all using(owner_id=auth.uid()) with check(owner_id=auth.uid()); create policy "own cursors" on public.sync_cursors for all using(owner_id=auth.uid()) with check(owner_id=auth.uid()); create policy "own changes" on public.sync_changes for select using(owner_id=auth.uid());
-- Apply this migration through the Supabase SQL editor before enabling sync. The RPC definitions are kept in docs/supabase-0004-rpc.sql because they exceed the dashboard migration preview limit.
